sp_widget.client_script:
api.controller = function($scope, $location, $anchorScroll, $window, $timeout) {
 var c = this;
 c.modal = { show: false };
 // Allow only same-app relative URLs
 function isSafeRelativeUrl(url) {
   if (typeof url !== 'string' || url === '') return false;
   if (/^https?:\/\//i.test(url)) return false;
   if (url.indexOf('//') === 0) return false;
   if (url.indexOf('\\') !== -1) return false;
   return true;
 }
 c.checkLoginAndRedirect = function(event) {
   event.preventDefault();
   // User is not logged in
   if (!c.data.isLoggedIn) {
     c.modal = {
       show: true,
       type: 'info',
       title: 'Authentication Required',
       message: 'You are not logged in. Please log in first to access the dashboard.',
       confirmLabel: 'Okay',
       confirmAction: function() {
         c.modal.show = false;
       }
     };
     return;
   }
   // Any logged-in user can access the dashboard
   if (isSafeRelativeUrl(c.data.dashboardUrl)) {
     $location.url(c.data.dashboardUrl);
   } else {
     console.warn(
       'checkLoginAndRedirect: unsafe or missing dashboardUrl, aborting redirect.'
     );
   }
 };
 c.logout = function(event) {
   if (event) event.preventDefault();
   c.modal = {
     show: true,
     type: 'info',
     title: 'Logged Out',
     message: 'You have been logged out successfully.',
     confirmLabel: 'Okay',
     confirmAction: function() {
       c.modal.show = false;
       $location.url('/?id=applicant_home');
     }
   };
 };
 c.onSecondary = function(event) {
   var target = c.data.secondaryUrl;
   if (!target || target.charAt(0) !== '#') return;
   event.preventDefault();
   var id = target.substring(1);
   var el = document.getElementById(id);
   if (el && el.scrollIntoView) {
     el.scrollIntoView({
       behavior: 'smooth',
       block: 'start'
     });
   } else {
     $location.hash(id);
     $anchorScroll();
   }
 };
};

sp_widget.css:
/* =========================================================
   GATENOW LANDING · HERO
   Service Portal widget · CSS / SCSS
   ========================================================= */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}

$gnl-navy:      #0a2540;
$gnl-blue:      #1560e0;
$gnl-blue-dk:   #0f4cbb;
$gnl-blue-soft: #e8f0fe;
$gnl-body:      #55677f;
$gnl-white:     #ffffff;

$gnl-shadow-soft: 0 12px 30px rgba(16, 54, 110, 0.10);
$gnl-shadow-btn:  0 14px 30px rgba(21, 96, 224, 0.30);

$gnl-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;

.gnl-hero {
  position: relative;
  width: 100%;
  padding: 112px 24px 130px;
  font-family: $gnl-font;
  color: $gnl-navy;
  text-align: center;
  overflow: hidden;
  background-color: #f2f7fe;
  background-image:
    radial-gradient(900px 520px at 50% -12%, rgba(206, 226, 252, 0.85), rgba(206, 226, 252, 0) 70%),
    radial-gradient(760px 520px at 100% 42%, rgba(214, 231, 253, 0.70), rgba(214, 231, 253, 0) 66%),
    radial-gradient(680px 460px at 0% 76%, rgba(226, 238, 253, 0.75), rgba(226, 238, 253, 0) 64%),
    linear-gradient(180deg, #f4f8fe 0%, #e9f1fd 52%, #f3f8fe 100%);
}

.gnl-hero *,
.gnl-hero *::before,
.gnl-hero *::after { box-sizing: border-box; }

.gnl-hero a { text-decoration: none; }
.gnl-hero a:hover,
.gnl-hero a:focus { text-decoration: none; }

.gnl-hero :focus-visible {
  outline: 2px solid $gnl-blue;
  outline-offset: 3px;
}

.gnl-hero__inner {
  max-width: 1080px;
  margin: 0 auto;
}

.gnl-hero .gnl-title {
  margin: 0;
  font-size: 88px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.028em;
  color: $gnl-navy;
}

@supports (font-size: clamp(38px, 6.1vw, 88px)) {
  .gnl-hero .gnl-title { font-size: clamp(38px, 6.1vw, 88px); }
}

.gnl-title__line { display: block; }

.gnl-title__accent { color: $gnl-blue; }

.gnl-title__stop {
  color: $gnl-navy;
  margin-left: 0.05em;
  letter-spacing: 0;
}

.gnl-hero .gnl-sub {
  display: block;
  max-width: 742px;
  margin: 46px auto 0;
  padding: 0;
  font-size: 20px;
  font-weight: 400;
  line-height: 1.58;
  letter-spacing: -0.005em;
  color: $gnl-body;
}

.gnl-hero .gnl-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 58px;
}

.gnl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  height: 72px;
  padding: 0 44px;
  border-radius: 999px;
  font-size: 17.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition: background 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease, color 0.22s ease;
}

.gnl-btn--primary {
  background: $gnl-blue;
  color: $gnl-white;
  box-shadow: $gnl-shadow-btn;
}

.gnl-btn--primary:hover {
  background: $gnl-blue-dk;
  color: $gnl-white;
  box-shadow: 0 18px 38px rgba(21, 96, 224, 0.38);
  transform: translateY(-2px);
}

.gnl-btn--ghost {
  background: $gnl-white;
  color: $gnl-navy;
  padding: 0 42px;
  box-shadow: $gnl-shadow-soft;
}

.gnl-btn--ghost:hover {
  color: $gnl-navy;
  box-shadow: 0 16px 36px rgba(16, 54, 110, 0.16);
  transform: translateY(-2px);
}

.gnl-play {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: $gnl-blue-soft;
  color: $gnl-blue;
  font-size: 11px;
  flex-shrink: 0;
}

.gnl-play i { margin-left: 2px; }

@media (max-width: 900px) {
  .gnl-hero { padding: 76px 20px 92px; }
  .gnl-hero .gnl-sub { font-size: 18px; margin-top: 34px; }
  .gnl-hero .gnl-actions { margin-top: 42px; gap: 16px; }
  .gnl-btn { height: 64px; padding: 0 34px; font-size: 16.5px; }
  .gnl-btn--ghost { padding: 0 32px; }
}

@media (max-width: 620px) {
  .gnl-hero { padding: 56px 18px 68px; }

  .gnl-hero .gnl-title { letter-spacing: -0.03em; }
  .gnl-hero .gnl-sub { font-size: 16px; }

  .gnl-hero .gnl-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .gnl-btn {
    width: 100%;
    height: 58px;
    font-size: 16px;
  }

  .gnl-btn--ghost { padding: 0 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnl-hero * { transition: none; }
  .gnl-btn:hover { transform: none; }
}

/* =========================================================
   GATENOW LANDING · MODAL
   ========================================================= */

.gn-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 37, 64, 0.55);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
  animation: gnFadeIn 0.2s ease-out;
}

.gn-modal {
  position: relative;
  width: 100%;
  max-width: 400px;
  background: $gnl-white;
  border-radius: 24px;
  padding: 44px 38px 36px;
  text-align: center;
  font-family: $gnl-font;
  box-shadow: 0 30px 60px rgba(10, 37, 64, 0.22);
  animation: gnPopIn 0.24s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.gn-modal-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gn-modal-icon svg {
  width: 30px;
  height: 30px;
}

.gn-icon-success {
  background: $gnl-blue-soft;
  color: #1e8e3e;
}

.gn-icon-info {
  background: $gnl-blue-soft;
  color: $gnl-blue;
}

.gn-modal-title {
  margin: 0 0 10px;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: $gnl-navy;
}

.gn-modal-message {
  margin: 0 0 30px;
  font-size: 15.5px;
  font-weight: 400;
  line-height: 1.55;
  letter-spacing: -0.005em;
  color: $gnl-body;
}

.gn-modal-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.gn-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 56px;
  padding: 0 32px;
  border: none;
  border-radius: 999px;
  background: $gnl-blue;
  color: $gnl-white;
  font-family: $gnl-font;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  cursor: pointer;
  box-shadow: $gnl-shadow-btn;
  transition: background 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease;
}

.gn-btn-primary:hover {
  background: $gnl-blue-dk;
  box-shadow: 0 18px 38px rgba(21, 96, 224, 0.38);
  transform: translateY(-2px);
}

.gn-btn-text {
  background: none;
  border: none;
  padding: 6px;
  font-family: $gnl-font;
  font-size: 14px;
  font-weight: 500;
  color: $gnl-body;
  cursor: pointer;
  transition: color 0.18s ease;
}

.gn-btn-text:hover {
  color: $gnl-navy;
}

.gn-modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 32px;
  height: 32px;
  border: none;
  background: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $gnl-body;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}

.gn-modal-close:hover {
  background: $gnl-blue-soft;
  color: $gnl-navy;
}

@keyframes gnFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes gnPopIn {
  from { opacity: 0; transform: scale(0.92) translateY(10px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

@media (max-width: 620px) {
  .gn-modal {
    padding: 36px 26px 28px;
    border-radius: 20px;
  }
  .gn-modal-title { font-size: 21px; }
  .gn-modal-message { font-size: 14.5px; }
  .gn-btn-primary { height: 52px; font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  .gn-modal-overlay,
  .gn-modal { animation: none; }
}

sp_widget.script:
(function() {
 data.headlineOne       = options.headline_one        || 'Win the funding';
 data.headlineTwoLead   = options.headline_two_lead   || 'Skip the';
 data.headlineTwoAccent = options.headline_two_accent || 'paperwork';
 data.subhead            = options.subhead             || 'Everything you need to find the right funding, apply with confidence, and manage your grant journey all in one place, from your first application through award and beyond.';
 data.primaryLabel       = options.primary_label       || 'See what\'s open';
 data.primaryUrl         = options.primary_url         || '?id=opportunities';
 data.dashboardLabel     = options.dashboard_label     || 'Dashboard';
 data.dashboardUrl       = options.dashboard_url       || '?id=applicant_dashboard';
 data.registerUrl        = options.register_url        || '?id=applicant_intake';
 // Check only whether the user is logged in
 data.isLoggedIn = gs.getSession().isLoggedIn();
})();
